// 辅助函数：获取所有省份
export const getProvinces = (): string[] => {
  return schoolsData.map(province => province.name)
}

// 辅助函数：根据省份获取城市列表
export const getCitiesByProvince = (provinceName: string): string[] => {
  const province = schoolsData.find(p => p.name === provinceName)
  return province ? province.cities.map(city => city.name) : []
}

// 辅助函数：根据省份和城市获取区县列表
export const getDistrictsByCity = (provinceName: string, cityName: string): string[] => {
  const province = schoolsData.find(p => p.name === provinceName)
  if (!province) return []
  
  const city = province.cities.find(c => c.name === cityName)
  return city ? city.districts.map(district => district.name) : []
}

// 辅助函数：根据省份、城市和区县获取学校列表
export const getSchoolsByDistrict = (provinceName: string, cityName: string, districtName: string): string[] => {
  const province = schoolsData.find(p => p.name === provinceName)
  if (!province) return []
  
  const city = province.cities.find(c => c.name === cityName)
  if (!city) return []
  
  const district = city.districts.find(d => d.name === districtName)
  return district ? district.schools.map(school => school.name) : []
}
